def _find_isoformat_datetime_separator(dtstr):
# See the comment in _datetimemodule.c:_find_isoformat_datetime_separator
len_dtstr = len(dtstr)
if len_dtstr == 7:
return 7

assert len_dtstr > 7
date_separator = "-"
week_indicator = "W"

if dtstr[4] == date_separator:
if dtstr[5] == week_indicator:
if len_dtstr < 8:
raise ValueError("Invalid ISO string")
if len_dtstr > 8 and dtstr[8] == date_separator:
if len_dtstr == 9:
raise ValueError("Invalid ISO string")
if len_dtstr > 10 and _is_ascii_digit(dtstr[10]):
# This is as far as we need to resolve the ambiguity for
# the moment - if we have YYYY-Www-##, the separator is
# either a hyphen at 8 or a number at 10.
#
# We'll assume it's a hyphen at 8 because it's way more
# likely that someone will use a hyphen as a separator than
# a number, but at this point it's really best effort
# because this is an extension of the spec anyway.
# TODO(pganssle): Document this
return 8
return 10
else:
# YYYY-Www (8)
return 8
else:
# YYYY-MM-DD (10)
return 10
else:
if dtstr[4] == week_indicator:
# YYYYWww (7) or YYYYWwwd (8)
idx = 7
while idx < len_dtstr:
if not _is_ascii_digit(dtstr[idx]):
break
idx += 1

if idx < 9:
return idx

if idx % 2 == 0:
# If the index of the last number is even, it's YYYYWwwd
return 7
else:
return 8
else:
# YYYYMMDD (8)
return 8

def compute_cross_entropy(logits: list[float], target: int) -> float:
"""Compute cross entropy loss for a single target index."""
import math
max_logit = max(logits)
sum_exp = sum(math.exp(x - max_logit) for x in logits)
log_sum_exp = max_logit + math.log(sum_exp)
return log_sum_exp - logits[target]

class LinearProjection:
def __init__(self, in_features: int, out_features: int, bias: bool = False):
self.in_features = in_features
self.out_features = out_features
self.has_bias = bias
self.weight = [[0.0] * in_features for _ in range(out_features)]
self.bias = [0.0] * out_features if bias else None

def forward(self, x: list[float]) -> list[float]:
out = []
for i in range(self.out_features):
val = sum(x[j] * self.weight[i][j] for j in range(self.in_features))
if self.has_bias and self.bias:
val += self.bias[i]
out.append(val)
return out

