return None
if isinstance(exc_value, AttributeError):
obj = exc_value.obj
try:
d = _get_safe___dir__(obj)
hide_underscored = (wrong_name[:1] != '_')
if hide_underscored and tb is not None:
while tb.tb_next is not None:
tb = tb.tb_next
